<option value="normal">1 atm (normal)</option>
<option value="low">Low pressure (sublimation)</option>
<option value="super">Supercritical (&gt;218 atm)</option>
</select>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0, 0, 600, 480);

// ── Coordinate mapping (nonlinear axes) ──
var PL = 95, PR = 555, PT = 42, PB = 405;
var PW = PR - PL, PH = PB - PT;

function xS(T) {
  if (T >= 0) return PL + (Math.log10(T + 1) / Math.log10(375)) * PW;
  return PL + T * 1.4;
}
function yS(p) {
  if (p <= 0.0001) p = 0.0001;
  return PB - ((Math.log10(p) + 3) / 5.398) * PH;
}

// ── Curve data ──
var boilPts = [[0.01,0.006],[10,0.012],[20,0.023],[30,0.042],[40,0.073],[50,0.122],[60,0.197],[70,0.307],[80,0.468],[90,0.692],[100,1.0],[120,1.96],[140,3.61],[160,6.18],[180,10.0],[200,15.3],[220,22.8],[240,33.0],[260,46.4],[280,63.6],[300,85.9],[320,112.8],[340,145.9],[360,186.5],[374,218]];
var meltPts = [];
for (var mp = 0.006; mp <= 218; mp += 4) meltPts.push([0.01 - 0.0075*(mp - 0.006), mp]);
meltPts.push([-1.62, 218]);
var subPts = [];
for (var sT = -25; sT <= 0.01; sT += 0.5) {
  var sp = 0.00603 * Math.exp(22.5 * sT / (273 + sT));
  subPts.push([sT, sp]);
}

function pSub(T) { if (T > 0.01) return 0; return 0.00603 * Math.exp(22.5*T/(273+T)); }
function tMelt(p) { return 0.01 - 0.0075*(p - 0.006); }
function pBoil(T) {
  if (T <= 0.01) return 0.006;
  if (T >= 374) return 218;
  for (var i = 1; i < boilPts.length; i++) {
    if (boilPts[i][0] >= T) {
      var t0 = boilPts[i-1][0], p0 = boilPts[i-1][1], t1 = boilPts[i][0], p1 = boilPts[i][1];
      var f = (T - t0)/(t1 - t0);
      return p0 + f*(p1 - p0);
    }
  }
  return 218;
}
function getPhase(T, p) {
  var tm = tMelt(p);
  if (T < tm) {
    if (T <= 0.01 && p <= pSub(T)) return 'v';
    return 's';
  }
  if (T <= 374 && p <= pBoil(T)) return 'v';
  if (T > 374 && p <= 218) return 'v';
  return 'l';
}

// ── Draw axes ──
var axisColor = '#222';
draw.line(PL, PB, PL, PT - 8).stroke({color: axisColor, width: 1.5}).marker('end', draw.marker(8,8,function(a){a.path('M0,0 L8,4 L0,8').fill(axisColor);}));
draw.line(PL, PB, PR + 8, PB).stroke({color: axisColor, width: 1.5}).marker('end', draw.marker(8,8,function(a){a.path('M0,0 L8,4 L0,8').fill(axisColor);}));

// Y-axis ticks
var yTicks = [0.006, 1, 218];
yTicks.forEach(function(p) {
  var y = yS(p);
  draw.line(PL - 4, y, PL, y).stroke({color: axisColor, width: 1});
  draw.text(p === 0.006 ? '0.006' : String(p)).attr({x: PL - 8, y: y, 'text-anchor':'end', 'dominant-baseline':'middle', 'font-size': 11, 'font-family':'sans-serif'});
});

// X-axis ticks
var xTicks = [0, 0.01, 100, 374];
xTicks.forEach(function(T) {
  var x = xS(T);
  draw.line(x, PB, x, PB + 4).stroke({color: axisColor, width: 1});
  draw.text(T === 0.01 ? '0.01' : String(T)).attr({x: x, y: PB + 14, 'text-anchor':'middle', 'font-size': 11, 'font-family':'sans-serif'});
});

// Axis labels
draw.text('Temperature, T (°C)').attr({x: (PL+PR)/2, y: PB + 35, 'text-anchor':'middle', 'font-size': 13, 'font-weight':'bold', 'font-family':'sans-serif'});
var yLabel = draw.text('Pressure, p (atm)').attr({'font-size': 13, 'font-weight':'bold', 'font-family':'sans-serif'});
yLabel.transform({rotate: -90, cx: 25, cy: (PT+PB)/2}).attr({x: 25, y: (PT+PB)/2, 'text-anchor':'middle'});

// Title
draw.text('H₂O').attr({x: 300, y: 22, 'text-anchor':'middle', 'font-size': 16, 'font-weight':'bold', 'font-family':'sans-serif'});

// ── Region highlight polygons (behind curves, initially invisible) ──
var regionGroup = draw.group();

function buildSolidPoly() {
  var pts = [];
  pts.push([PL, PT]);
  for (var i = meltPts.length - 1; i >= 0; i--) pts.push([xS(meltPts[i][0]), yS(meltPts[i][1])]);
  for (var i = subPts.length - 1; i >= 0; i--) pts.push([xS(subPts[i][0]), yS(subPts[i][1])]);
  pts.push([PL, PB]);
  return pts;
}
function buildLiquidPoly() {
  var pts = [];
  for (var i = 0; i < meltPts.length; i++) pts.push([xS(meltPts[i][0]), yS(meltPts[i][1])]);
  pts.push([xS(374), PT]);
  for (var i = boilPts.length - 1; i >= 0; i--) pts.push([xS(boilPts[i][0]), yS(boilPts[i][1])]);
  return pts;
}
function buildVaporPoly() {
  var pts = [];
  pts.push([xS(0.01), yS(0.006)]);
  for (var i = subPts.length - 1; i >= 0; i--) pts.push([xS(subPts[i][0]), yS(subPts[i][1])]);
  pts.push([PL, PB]);
  pts.push([PR, PB]);
  pts.push([PR, yS(218)]);
  for (var i = boilPts.length - 1; i >= 0; i--) pts.push([xS(boilPts[i][0]), yS(boilPts[i][1])]);
  return pts;
}

function polyStr(pts) { return pts.map(function(p){return p[0]+','+p[1];}).join(' '); }

var solidPoly = regionGroup.polygon(polyStr(buildSolidPoly())).fill({color:'#b0b0b0', opacity:0}).stroke('none');
var liquidPoly = regionGroup.polygon(polyStr(buildLiquidPoly())).fill({color:'#7fb3ff', opacity:0}).stroke('none');
var vaporPoly = regionGroup.polygon(polyStr(buildVaporPoly())).fill({color:'#ffcc80', opacity:0}).stroke('none');

// ── Draw coexistence curves ──
var curveColor = '#cc2222';
function drawCurve(pts) {
  var d = 'M' + pts.map(function(p){return xS(p[0])+','+yS(p[1]);}).join(' L');
  return draw.path(d).fill('none').stroke({color: curveColor, width: 2.2, linecap:'round', linejoin:'round'});
}
drawCurve(subPts);
drawCurve(meltPts);
drawCurve(boilPts);

// ── Dashed guide lines ──
var dashStyle = {color:'#666', width: 1, dasharray: '4,3'};
var tpX = xS(0.01), tpY = yS(0.006);
draw.line(PL, tpY, tpX, tpY).stroke(dashStyle);
draw.line(tpX, tpY, tpX, PB).stroke(dashStyle);
var cpX = xS(374), cpY = yS(218);
draw.line(PL, cpY, cpX, cpY).stroke(dashStyle);
draw.line(cpX, cpY, cpX, PB).stroke(dashStyle);
var bX = xS(100), bY = yS(1);
draw.line(PL, bY, bX, bY).stroke(dashStyle);
draw.line(bX, bY, bX, PB).stroke(dashStyle);

// ── Triple point and Critical point dots ──
draw.circle(7).center(tpX, tpY).fill('#111');
draw.circle(7).center(cpX, cpY).fill('#111');

// Triple point label — offset further below-right to avoid collision
draw.text('Triple').attr({x: tpX + 12, y: tpY + 14, 'font-size': 10, 'font-family':'sans-serif'});
draw.text('point').attr({x: tpX + 12, y: tpY + 26, 'font-size': 10, 'font-family':'sans-serif'});

// Critical point label — above-left
draw.text('Critical point').attr({x: cpX - 5, y: cpY - 12, 'text-anchor':'end', 'font-size': 11, 'font-weight':'bold', 'font-family':'sans-serif'});

// ── Region labels (italic) ──
draw.text('s').attr({x: xS(-8), y: yS(5), 'font-size': 16, 'font-style':'italic', 'font-family':'serif', 'text-anchor':'middle'});
draw.text('l').attr({x: xS(30), y: yS(50), 'font-size': 16, 'font-style':'italic', 'font-family':'serif', 'text-anchor':'middle'});
draw.text('v').attr({x: xS(250), y: yS(0.5), 'font-size': 16, 'font-style':'italic', 'font-family':'serif', 'text-anchor':'middle'});

// ── Curved arrow annotations ──
function curvedArrow(x1,y1,cx,cy,x2,y2,label,lx,ly,anchor) {
  var d = 'M'+x1+','+y1+' Q'+cx+','+cy+' '+x2+','+y2;
  draw.path(d).fill('none').stroke({color:'#222', width:1.2}).marker('end', draw.marker(7,7,function(a){a.path('M0,0 L7,3.5 L0,7').fill('#222');}));
  draw.text(label).attr({x:lx, y:ly, 'font-size':11, 'font-family':'sans-serif', 'text-anchor': anchor || 'start'});
}
// Melting arrow (points at melting curve from left)
curvedArrow(xS(-15), yS(80), xS(-12), yS(100), xS(-0.8), yS(120), 'Melting', xS(-20), yS(70));
// Boiling arrow (points at boiling curve from right)
curvedArrow(xS(320), yS(60), xS(300), yS(80), xS(280), yS(70), 'Boiling', xS(330), yS(55));
// Sublimation arrow (points at sublimation curve from lower-left)
curvedArrow(xS(-22), yS(0.0015), xS(-18), yS(0.002), xS(-12), yS(0.003), 'Sublimation', xS(-25), yS(0.0012));

// ── Heating path (initially hidden) ──
var pathGroup = draw.group();
pathGroup.hide();

function drawHeatingPath(p) {
  pathGroup.clear();
  var y = yS(p);
  if (y < PT || y > PB) return;
  pathGroup.line(PL, y, PR, y).stroke({color:'#2266cc', width: 1.5, dasharray:'6,3'});

  // Find crossings
  var crossings = [];
  if (p < 0.006 && p > 0.0005) {
    for (var T = -25; T <= 0; T += 0.1) {
      if (pSub(T) >= p) { crossings.push({T: T, label:'Sublimation'}); break; }
    }
  }
  if (p > 0.006) {
    var tm = tMelt(p);
    if (tm >= -25 && tm <= 374) crossings.push({T: tm, label:'Melting'});
  }
  if (p > 0.006 && p < 218) {
    for (var i = 1; i < boilPts.length; i++) {
      if (boilPts[i][1] >= p) {
        var t0=boilPts[i-1][0], p0=boilPts[i-1][1], t1=boilPts[i][0], p1=boilPts[i][1];
        var f = (p-p0)/(p1-p0);
        crossings.push({T: t0+f*(t1-t0), label:'Boiling'});
        break;
      }
    }
  }

  crossings.forEach(function(c) {
    var cx = xS(c.T);
    if (cx >= PL && cx <= PR) {
      pathGroup.circle(8).center(cx, y).fill('#2266cc').stroke({color:'#fff',width:1});
      // Only show label if it won't duplicate existing annotations
      // The curved arrows already label Melting, Boiling, Sublimation
      // So we show small markers only, no text labels
    }
  });
}

// ── State point (initially hidden) ──
var stateDot = draw.circle(10).fill('#e63946').stroke({color:'#fff', width:2}).css('cursor','pointer');
stateDot.hide();
stateDot.on('mousemove', function(e){ showTooltip('State point: T=' + curT.toFixed(1) + '°C, p=' + curP.toFixed(2) + ' atm — Phase: ' + getPhase(curT, curP).toUpperCase(), e); });
stateDot.on('mouseleave', hideTooltip);

// ── State variables ──
var curT = 25, curP = 1;
var showPath = false;
var pathMode = 'normal';
var showStatePoint = false;
var showFills = false;

function getPathPressure() {
  if (pathMode === 'normal') return 1;
  if (pathMode === 'low') return 0.004;
  return 230;
}

function updateFigure() {
  // State point
  if (showStatePoint) {
    var x = xS(curT), y = yS(curP);
    x = Math.max(PL - 20, Math.min(PR + 10, x));
    y = Math.max(PT - 10, Math.min(PB + 10, y));
    stateDot.center(x, y);
    stateDot.show();
  } else {
    stateDot.hide();
  }

  // Region highlight
  if (showFills) {
    var phase = getPhase(curT, curP);
    solidPoly.fill({color:'#b0b0b0', opacity: phase==='s' ? 0.18 : 0});
    liquidPoly.fill({color:'#7fb3ff', opacity: phase==='l' ? 0.18 : 0});
    vaporPoly.fill({color:'#ffcc80', opacity: phase==='v' ? 0.18 : 0});
  } else {
    solidPoly.fill({color:'#b0b0b0', opacity: 0});
    liquidPoly.fill({color:'#7fb3ff', opacity: 0});
    vaporPoly.fill({color:'#ffcc80', opacity: 0});
  }

  // Heating path
  if (showPath) {
    drawHeatingPath(getPathPressure());
    pathGroup.show();
  } else {
    pathGroup.hide();
  }
}

function update_temperature(v) { curT = v; showStatePoint = true; showFills = true; updateFigure(); }
function update_pressure(v) { curP = v; showStatePoint = true; showFills = true; updateFigure(); }
function toggle_heatingPath(on) { showPath = on; updateFigure(); }
function update_pathMode(v) { pathMode = v; updateFigure(); }

// ── Demo steps ──
var steps = [
  {title:'Phase = location', narration:'This is the phase diagram of water. The three red curves separate solid (s), liquid (l), and vapor (v) regions. Use the steps to explore how the state point\'s position determines the phase.', T:25, p:1, path:false, mode:'normal', showPoint:false, showFill:false},
  {title:'Pressure melts ice', narration:'Hold temperature just below 0 °C and raise the pressure slider. The point crosses the leftward-leaning melting curve and the highlighted region flips from solid to liquid — squeezing ice turns it to water.', T:-1, p:1, path:false, mode:'normal', showPoint:true, showFill:true},
  {title:'Normal heating at 1 atm', narration:'At 1 atm the horizontal path crosses the melting line near 0 °C (solid→liquid) and the boiling line at 100 °C (liquid→vapor) — the everyday sequence.', T:25, p:1, path:true, mode:'normal', showPoint:true, showFill:true},
  {title:'Low-pressure: sublimation', narration:'Drop the path below the triple-point pressure (0.006 atm). The line crosses only the sublimation curve: solid turns directly to vapor with no liquid stage.', T:25, p:0.004, path:true, mode:'low', showPoint:true, showFill:true},
  {title:'Supercritical heating', narration:'Above 218 atm the line crosses no coexistence curve: liquid and vapor merge into one supercritical fluid — no sharp boiling transition.', T:380, p:230, path:true, mode:'super', showPoint:true, showFill:true}
];
var curStep = 0;

function applyStep(i) {
  curStep = i;
  var s = steps[i];
  curT = s.T; curP = s.p; showPath = s.path; pathMode = s.mode;
  showStatePoint = s.showPoint; showFills = s.showFill;
  document.getElementById('temperatureInput').value = curT;
  document.getElementById('temperatureVal').value = curT;
  document.getElementById('pressureInput').value = curP;
  document.getElementById('pressureVal').value = curP;
  document.getElementById('heatingPathInput').checked = showPath;
  document.getElementById('heatingPathSelect').value = s.mode;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (i+1) + '/' + steps.length;
  updateFigure();
}
function nextStep() { applyStep(Math.min(curStep + 1, steps.length - 1)); }
function prevStep() { applyStep(Math.max(curStep - 1, 0)); }

// Initial render — clean diagram matching source
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

